package storage

import "fmt"

// ErrNotFound represents a not found error
type ErrNotFound string

// ErrNotFoundf creates an ErrNotFound using a custom format
func ErrNotFoundf(format string, args ...interface{}) error {
	return ErrNotFound(fmt.Sprintf(format, args...))
}

func (e ErrNotFound) Error() string {
	return fmt.Sprintf("%s not found", string(e))
}

// ErrInvalid represents an invalid error
type ErrInvalid string

// ErrInvalidf creates an ErrInvalid using a custom format
func ErrInvalidf(format string, args ...interface{}) error {
	return ErrInvalid(fmt.Sprintf(format, args...))
}

func (e ErrInvalid) Error() string {
	return string(e)
}
package server

import "fmt"

// errInvalidField represents a validation error
type errInvalidField struct {
	field  string
	reason string
}

func (e errInvalidField) Error() string {
	return fmt.Sprintf("invalid field %s: %s", e.field, e.reason)
}

// invalidFieldError creates an errInvalidField for a specific field and reason
func invalidFieldError(field, reason string) error {
	return errInvalidField{field, reason}
}

// emptyFieldError creates an errInvalidField for an empty field
func emptyFieldError(field string) error {
	return invalidFieldError(field, "must not be empty")
}
package storage

import (
	"database/sql"
	"database/sql/driver"
	"fmt"
	"net/url"
	"time"

	"github.com/golang/protobuf/ptypes"
	proto "github.com/golang/protobuf/ptypes/timestamp"
	"github.com/pkg/errors"
)

type timestamp struct {
	*proto.Timestamp
}

func (t *timestamp) Scan(value interface{}) error {
	v, ok := value.(time.Time)
	if ok {
		val, err := ptypes.TimestampProto(v)
		if err != nil {
			return err
		}
		t.Timestamp = val
	}
	return nil
}

func (t *timestamp) Value() (driver.Value, error) {
	return ptypes.Timestamp(t.Timestamp)
}

const (
	pgConstraintForeignKey = "foreign_key_violation"
	pgConstraintUnique     = "unique_violation"
)

// Open opens a connection to the db given a URL
func Open(url string) (*sql.DB, Driver, error) {
	driver, u, err := parse(url)
	if err != nil {
		return nil, 0, err
	}

	db, err := sql.Open(driver.String(), u.String())
	if err != nil {
		return nil, 0, err
	}

	return db, driver, nil
}

var (
	driverToString = map[Driver]string{
		SQLite:   "sqlite3",
		Postgres: "postgres",
	}

	schemeToDriver = map[string]Driver{
		"file":     SQLite,
		"postgres": Postgres,
	}
)

// Driver represents a database driver type
type Driver uint8

func (d Driver) String() string {
	return driverToString[d]
}

const (
	_ Driver = iota
	// SQLite ...
	SQLite
	// Postgres ...
	Postgres
)

func parse(in string) (Driver, *url.URL, error) {
	u, err := url.Parse(in)
	if err != nil {
		return 0, u, errors.Wrapf(err, "parsing url: %q", in)
	}

	driver := schemeToDriver[u.Scheme]
	if driver == 0 {
		return 0, u, fmt.Errorf("unknown database driver for: %s", u.Scheme)
	}

	if driver == SQLite {
		v := u.Query()
		v.Set("cache", "shared")
		v.Set("_fk", "true")
		u.RawQuery = v.Encode()
	}

	return driver, u, nil
}

